const onClick = (e: React.MouseEvent<HTMLButtonElement>) => {};
const onKey = (e: React.KeyboardEvent<HTMLInputElement>) => { if (e.key === "Enter") {} };

interface ListProps<T> {
  items: T[];
  render: (item: T) => React.ReactNode;
  getKey: (item: T) => string | number;
}

export function List<T>({ items, render, getKey }: ListProps<T>) {
  return <ul>{items.map((i) => <li key={getKey(i)}>{render(i)}</li>)}</ul>;
}

type ButtonProps = React.ComponentPropsWithoutRef<"button"> & {
  variant?: "primary" | "ghost";
};

export function Button({ variant = "primary", ...rest }: ButtonProps) {
  return <button data-variant={variant} {...rest} />;
}

function isString(x: unknown): x is string {
  return typeof x === "string";
}

type Result = { ok: true; data: string } | { ok: false; error: string };
function show(r: Result) {
  if (r.ok) return r.data;      // narrowed to the ok branch
  return r.error;
}

export async function getJson<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init);
  if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
  return (await res.json()) as T;
}
